public static String appx(String word1, String word2) {
    int commonLetters = 0;
    for (int i = 0; i < word1.length(); i++) {
        for (int j = 0; j < word2.length(); j++) {
            if (word1.charAt(i) == word2.charAt(j)) {
                commonLetters++;
                break;
            }
        }
    }
    int denominator = word1.length() + word2.length();
    int numerator = commonLetters;
    int gcd = gcd(numerator, denominator);
    numerator /= gcd;
    denominator /= gcd;
    return "appx(" + word1 + ", " + word2 + ") = " + numerator + "/" + denominator;
}

public static int gcd(int a, int b) {
    if (b == 0) {
        return a;
    }
    return gcd(b, a % b);
}

public static String convertDatesToWeekdays(String date) {
    String[] dateParts = date.split(" ");
    int month = Integer.parseInt(dateParts[0]);
    int day = Integer.parseInt(dateParts[1]);
    int year = Integer.parseInt(dateParts[2]);
    Calendar calendar = Calendar.getInstance();
    calendar.set(year, month - 1, day);
    int weekday = calendar.get(Calendar.DAY_OF_WEEK);
    String weekdayName = "";
    switch (weekday) {
        case Calendar.SUNDAY:
            weekdayName = "Sunday";
            break;
        case Calendar.MONDAY:
            weekdayName = "Monday";
            break;
        case Calendar.TUESDAY:
            weekdayName = "Tuesday";
            break;
        case Calendar.WEDNESDAY:
            weekdayName = "Wednesday";
            break;
        case Calendar.THURSDAY:
            weekdayName = "Thursday";
            break;
        case Calendar.FRIDAY:
            weekdayName = "Friday";
            break;
        case Calendar.SATURDAY:
            weekdayName = "Saturday";
            break;
    }
    return weekdayName;
}

