    int len = 0;
    for (int i = 0; i < arr.length; i++) {
        int low = 0, high = len - 1;
        while (low <= high) {
            int mid = (low + high) / 2;
            if (arr[i] > arr[dp[mid]]) {
                low = mid + 1;
